values
  ('d141b42a-3707-4a4b-8343-702d2e0b338f','magic-chess-go-go','Magic Chess: Go Go','Magic Chess: Go Go Diamonds','Top up Diamonds for Magic Chess: Go Go. Enter your User ID and Zone ID, pick a diamond pack or the Weekly Diamond Pass, and diamonds are credited to your account.','img/games/magic-chess-go-go.jpg','img/games/magic-chess-go-go.jpg','Auto Battler','Diamonds','yokcash','active',15,'[{"title":"Enter Account Details","description":"Provide your Magic Chess: Go Go User ID and Zone ID."},{"title":"Choose the Package","description":"Select the diamond pack you want."},{"title":"Make Payment","description":"Choose your preferred payment method."},{"title":"Confirmation","description":"Diamonds are credited after payment."}]'::jsonb,'Diamonds are delivered to the User ID + Zone ID you enter — double-check them before paying.','{"source":"kazutora:Magic Chess Go Go","package_layout":"compact","pricing_source":"kazutora.in","package_sections":[{"type":"grid","title":"TOP UP DIAMONDS","product_ids":["32ab5660-ea8c-4609-8c0f-b26e4254647c","8e677f83-a898-461b-99a5-349798a633b0","0dce9b1b-9359-479f-8e42-544066d87f23","52807d57-6659-415f-b351-e1333c553497","f0866078-af8d-4697-b77b-3602f9cd3687","d335276d-ef1b-4163-bdaf-8e8299e1dacb","ae856ab5-dcd5-4e43-acf4-16ade4f4732c","7373b4a0-a234-4918-98c6-a407e18b0040","d6ceaadd-3dca-4a20-92c1-2d0ee0cb9c44","8f52f5b5-0a35-4353-b233-6dfe0dc6b392","5a50fef3-fdaf-4eb9-9547-b627273ca1c7"]},{"type":"grid","title":"DOUBLE DIAS PACKS","product_ids":["d15766f9-0734-4d79-928d-1ae0b3da5083","86a2d7e2-8b12-4dc9-bb4e-45a9d879397c","29df72a8-dbc3-412c-bc8f-3ffcb4fcccb1","4031dc8d-ca4e-4b67-a4a6-ab858f4485c1"]}]}'::jsonb),
  ('3a19efe8-7c80-483d-8d4c-ed72a1faa137','bgmi-not-instant','BGMI (Not Instant)','Battlegrounds Mobile India UC — Manual Delivery','Top up UC for Battlegrounds Mobile India at budget prices. This is not an instant top-up — our team processes each order manually after payment. Enter your numeric Character ID and pick a UC pack.','img/games/bgmi-not-instant.webp','img/games/bgmi-not-instant.webp','Battle Royale','UC','manual','active',16,'[{"title":"Enter Character ID","description":"Provide your numeric BGMI Character ID from your in-game profile."},{"title":"Choose the Package","description":"Select the UC pack you want."},{"title":"Make Payment","description":"Choose your preferred payment method."},{"title":"Manual Delivery","description":"Our team delivers the UC manually — not instant, allow processing time."}]'::jsonb,'This is NOT an instant top-up. Orders are processed manually by our team after payment — delivery takes longer than the instant BGMI listing. UC is delivered to the Character ID you enter — double-check it before paying.','{"source":"kazutora:BGMI NOT INSTANT","package_layout":"compact","pricing_source":"kazutora.in","fulfillment_mode":"manual","package_sections":[{"type":"grid","title":"UC TOP UP","product_ids":["2747fdaf-ff85-47a7-9bdb-bbfe380c328b","e50fc369-6bdb-4001-90e2-e6d08f7f487f","ca282a8c-2d70-4798-96b2-fde1ea1b45f5","a34ead3c-8ebb-4d96-aaaf-d6bbd103c28b","9c57c85d-d48f-4a13-8a97-f1c8222e3a35","9af7cc50-823b-4a53-9b7b-da7709f906d4","d8017f23-88ce-4a45-ac50-e58bced280ad","4389d093-c1f3-4bc3-8636-0c62f91d8eb7"]},{"type":"grid","title":"UC BONUS TOP UP","product_ids":["9cedf138-32f2-4a5a-b80d-47cc9d61bbc7","d35600ff-8f3c-4f4a-8d60-536081d90114","fbbbfaf2-c4a6-4294-9bc8-3db9521978e3","bfe9f176-d9e9-4552-961e-e654b35e348e","5dd7d01a-06bf-4a64-a737-41ee573cdd96","93c4aa36-6472-40c7-ae96-af2cbc344f3a","b5c714d4-d644-4362-acba-fa2960bdf6bd","290ebc54-80a7-4d4c-ac47-12b4868d6c98","0708b12a-d70c-4daa-bf67-fc0f2cbdb08a"]},{"type":"grid","title":"EXTRA PACKS","product_ids":["6d327b93-4f44-4d85-8649-fca3f605ba50","d08616cf-5856-456c-8e50-7c830b42dd99","7c49e405-e94e-46af-81bb-f1c5c372dbcb","172ee949-b065-4dd6-b360-f39a7dd916cb"]}]}'::jsonb),
  ('e969f7be-91b8-4e1f-9374-198d511c2396','pubg-global','PUBG Mobile Global','PUBG Mobile UC (Global)','Top up UC for PUBG Mobile Global. Enter your numeric Player ID, pick a UC pack, and UC is credited to your account.','img/games/pubg-global.jpg','img/games/pubg-global.jpg','Battle Royale','UC','yokcash','active',17,'[{"title":"Enter Player ID","description":"Provide your numeric PUBG Mobile Player ID from your in-game profile."},{"title":"Choose the Package","description":"Select the UC pack you want."},{"title":"Make Payment","description":"Choose your preferred payment method."},{"title":"Confirmation","description":"UC is credited after payment."}]'::jsonb,'For PUBG Mobile Global accounts only — not BGMI. UC is delivered to the Player ID you enter; double-check it before paying.','{"source":"kazutora:PUBG GLOBAL","pricing_source":"kazutora.in"}'::jsonb),
  ('b2b7805a-4473-4c4f-9fb5-40da16307f9c','honkai-star-rail','Honkai: Star Rail','Oneiric Shards','Top up Oneiric Shards for Honkai: Star Rail. Enter your UID and server, pick a shard pack or the Express Supply Pass, and it is delivered straight to your account.','img/games/honkai-star-rail.webp','img/games/honkai-star-rail.webp','RPG','Oneiric Shard','yokcash','active',18,'[{"title":"Enter UID & Server","description":"Provide your Honkai: Star Rail UID and select the correct server."},{"title":"Choose the Package","description":"Select the Oneiric Shard pack or Express Supply Pass."},{"title":"Make Payment","description":"Choose your preferred payment method."},{"title":"Confirmation","description":"Shards are credited after payment — restart the game to see them."}]'::jsonb,'Shards go to the UID + server you enter. Wrong server = wrong account — check before paying.','{"source":"kazutora:HONKAI STAR RAIL","pricing_source":"kazutora.in"}'::jsonb),
  ('8b6f2ddf-1513-4e1e-baf4-a642d77cad21','revelation-mobile','Revelation Mobile','Revelation Mobile Top Up','Recharge your Revelation Mobile account. Enter your User ID and pick a pack — the Battle Pass Classic is delivered to your account after payment.','img/games/revelation-mobile.webp','img/games/revelation-mobile.webp','MMORPG','Battle Pass','yokcash','active',19,'[{"title":"Enter User ID","description":"Provide your Revelation Mobile User ID."},{"title":"Choose the Package","description":"Select the Battle Pass Classic pack."},{"title":"Make Payment","description":"Choose your preferred payment method."},{"title":"Confirmation","description":"The pass is credited after payment."}]'::jsonb,'Delivered to the User ID you enter — double-check it before paying.','{"source":"kazutora:Revelation Mobile","pricing_source":"kazutora.in"}'::jsonb)
